\begin{theorem}[Holomorphic defect formula]\label{thm:holomorphic_defect}
Let \(\Gamma\) be a finite union of positively oriented rectifiable Jordan curves enclosing the spectra of \(A_f\) and \(A_c\). If \(g\) is holomorphic on a neighborhood of the enclosed region, then
\[
Cg(A_f)-g(A_c)C
=
\frac{1}{2\pi\ii}
\int_\Gamma
 g(z)R_c(z)\Delta R_f(z)
\dd z.
\]
In particular,
\[
\begin{aligned}
\norm{Cg(A_f)-g(A_c)C}
\leq{}&
\frac{\operatorname{length}(\Gamma)}{2\pi}
\sup_{z\in\Gamma}\abs{g(z)}
\sup_{z\in\Gamma}\norm{R_c(z)}
\sup_{z\in\Gamma}\norm{R_f(z)}
\norm\Delta.
\end{aligned}
\]
\end{theorem}

